#!/usr/bin/env python3
"""Authors the SIXTH and last day of the Six-Day War (10 June 1967: Golan finish, Quneitra, ceasefire) for /war/: writes war/data/1967-06-10.json (page text + timeline), war/data/1967-06-10-events.json
(places, events, animation scene) and adds the day-3 casualty events ("jun10") to war/data/1967-casualties.json.

Same rules as the earlier days: every event carries a short quote from a pinned he.wikipedia revision (elisions marked [...], names of anyone killed left out), times are
the article's own wording, everything not given a coordinate is drawn SCHEMATICALLY and labelled so. Run: python3 tools/war_data_1967_06_10.py
"""
import copy
import json
from pathlib import Path
DATA = Path(__file__).resolve().parent.parent / "war" / "data"
D1 = json.loads((DATA / "1967-06-05-events.json").read_text(encoding="utf-8"))
D3 = json.loads((DATA / "1967-06-09-events.json").read_text(encoding="utf-8"))
CAS = json.loads((DATA / "1967-casualties.json").read_text(encoding="utf-8"))

def pl(name, lat, lon, basis_kind="נקודת המקום"):
    return {"name": name, "lat": lat, "lon": lon, "precision": "exact", "basis": f'קואורדינטות הערך "{name}" בוויקיפדיה העברית ({basis_kind})'}
PLACES = copy.deepcopy(D3["places"])
def pen(name, lat, lon, kind="נקודת היישוב"):
    return {"name": name, "lat": lat, "lon": lon, "precision": "exact", "basis": f'קואורדינטות הערך "{name}" בוויקיפדיה (עברית או אנגלית; {kind})'}
PLACES.update({
    "faher": pl("קרב תל פאחר", 33.224724, 35.69134, "נקודת הקרב"), "azz": pl("תל עזזיאת", 33.2256, 35.6669), "zaura": pl("זעורה", 33.169434, 35.71178), "einfit": pl("עין פית", 33.22388889, 35.70416667),
    "sirdib": pl("סיר א-דיב", 33.18330556, 35.6915), "dardara": pl("דרדרה", 33.052004, 35.639827), "tawfiq": pl("תאופיק", 32.7025, 35.63166667), "kuneitra": pl("קוניטרה", 33.11666667, 35.81666667),
    "gonen": pl("גונן", 33.12438312, 35.6468832), "givatem": pl("גבעת האם", 33.21166667, 35.65861111), "banias": pen("בניאס", 33.24861111, 35.69444444), "masada": pen("מסעדה", 33.23305556, 35.7575),
    "dan2": pl("קיבוץ דן", 33.23994812, 35.6535801), "naf": pl("הקרב על נפח", 33.053, 35.736, "נקודת צומת נפח"), "kfarharub": pen("כפר חרוב", 32.7625, 35.66361111), "afik": pen("אפיק", 32.77972222, 35.70138889),
    "rudeis": pl("אבו רודס", 28.891577, 33.184204),
    "fiq": pl("פיק", 32.76666667, 35.7), "naf": {"name": "צומת נפח", "lat": 33.053, "lon": 35.736, "precision": "exact", "basis": 'קואורדינטות הערך "הקרב על נפח" בוויקיפדיה העברית (נקודת הצומת)'}, "knaan": pl("הר כנען", 32.9798233, 35.5067326), "customs": pl("בית המכס העליון", 33.01147, 35.65115)})
P = {k: [v["lat"], v["lon"]] for k, v in PLACES.items()}
AREAS = {"lahfan": D1["areas"]["lahfan"]}
SRC = copy.deepcopy(D1["source"])  # the page credits every revision it quotes: the day-1 list plus the articles this day also quotes
SRC["articles"]['תקרית ליברטי'] = {"revid": 43991651}
EVENTS = []
def ev(i, area, clock, a, b, unit, title, quote, geom=None, nopos=None, note="", prec="exact", at=0):
    EVENTS.append({"id": i, "t": clock, "time_label": clock, "start_min": a, "end_min": b, "time_precision": prec, "unit": unit, "title": title, "quote": quote,
                   "geometry": geom or [], "no_position": nopos or [], "note": note, "area": area, "_at": at})
mk = lambda place, kind, note="": {"type": "marker", "place": place, "kind": kind, "note": note}
tr = lambda a, b, label: {"type": "track", "from": a, "to": b, "label": label}
# ---------------- sinai ----------------
ev("s0", "sinai", "10 ביוני", 0, 1440, "tank", "ישראל מודיעה על נכונותה לשלם פיצויים לנפגעי ליברטי",
   'ב-10 ביוני 1967 הודיעה ממשלת ישראל על נכונותה לשלם פיצויים לנפגעים.', [mk("liberty", "fight", "ליברטי: מיקום משוער")], prec="approximate", note="הערך לא נותן שעה", at=147)
